parts.program:
const int LED1 = 8;
const int LED2 = 9;
const int BUZZER = 10;

void setup() {
  pinMode(LED1, OUTPUT);
  pinMode(LED2, OUTPUT);
  pinMode(BUZZER, OUTPUT);
}

void loop() {
  digitalWrite(LED1, HIGH);
  delay(500);
  digitalWrite(LED1, LOW);
  digitalWrite(LED2, HIGH);
  tone(BUZZER, 1000);
  delay(500);
  digitalWrite(LED2, LOW);
  noTone(BUZZER);
}
